using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
#if NET8_0_OR_GREATER
using System.Runtime.InteropServices;
#endif

namespace Tedd;

public static class AddExtensions
{
    /// <summary>
    /// Gets the value associated with the specified key or adds a new value generated by the provided factory if the key does not exist.
    /// Time complexity: O(1)
    /// Space complexity: O(1)
    /// </summary>
    public static TValue GetOrAdd<TKey, TValue>(this Dictionary<TKey, TValue> dic, TKey key, Func<TValue> valueFactory)
    {
        if (key is null)
            throw new ArgumentNullException(nameof(key));
        if (valueFactory is null)
            throw new ArgumentNullException(nameof(valueFactory));

#if NET8_0_OR_GREATER
#pragma warning disable CS8714
        ref var val = ref CollectionsMarshal.GetValueRefOrAddDefault(dic, key, out bool exists);
#pragma warning restore CS8714
        if (!exists)
        {
            try
            {
                val = valueFactory();
            }
            catch
            {
                // Remove the key that was added by GetValueRefOrAddDefault if the factory throws
                dic.Remove(key);
                throw;
            }
        }

        return val!;
#else
        // Return if we have it
        if (dic.TryGetValue(key, out var value))
            return value;

        // Generate it
        value = valueFactory();
        dic.Add(key, value);

        return value;
#endif
    }
}
